import {account} from './account-client.js';
import {NoteStore} from './note-store.js?v=9';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const notes=new NoteStore(account,localStorage);
const timers=new Map();
export const notePlaceholder=id=>`<section class="question-note" data-note-id="${escape(id)}"></section>`;
function status(s){if(s.conflict)return'另一设备有更新；你的草稿已保留，请对比后选择。';if(s.storageError)return !s.dirty&&s.availability==='cloud'?'已保存到云端；本机缓存未能保存。':'本机草稿未能保存，请复制留存或重试云端保存。';if(s.error)return s.error;if(s.saving)return s.availability==='local'?'正在保存到本机…':'正在保存到云端…';if(s.dirty)return s.availability==='local'?'草稿已保存在本机，正在保存…':s.availability==='migration'?'草稿已保存在本机；管理员启用云端备注后可同步。':'草稿已保存在本机，等待云端保存…';if(s.availability==='migration')return'云端备注待管理员启用；输入内容会先保存在本机。';if(s.availability==='offline')return'暂未连接云端，显示本机缓存；输入内容会保留为草稿。';return s.availability==='local'?'备注保存在本机浏览器。':'备注跟随账户保存。';}
function body(id){const s=notes.get(id);return `<p class="note-preview" ${s.text?'':'hidden'}></p><details class="note-editor"><summary>我的备注${s.text?' · 编辑':' · 添加'}</summary><label>记录思路、易错点或待复习内容<textarea data-note-text maxlength="10000" rows="4" placeholder="例如：这题需要先判断积分区域的正负；复习第6章的商法则。" spellcheck="false">${escape(s.text)}</textarea></label><div class="note-controls"><button type="button" class="secondary" data-note-save>保存备注</button><small data-note-count>${s.text.length}/10000</small></div><p class="note-status" role="status" aria-live="polite"></p>${account.user?.is_admin&&s.availability==='migration'?'<a class="text-button note-setup-link" href="notes-setup.html">管理员：启用云端备注 ↗</a>':''}<div class="note-conflict" ${s.conflict?'':'hidden'}><label>云端最新备注<textarea data-note-remote readonly rows="3">${escape(s.cloudText)}</textarea></label><div class="button-row"><button type="button" class="secondary" data-note-use-cloud>使用云端内容</button><button type="button" class="secondary" data-note-keep>将我的草稿保存到云端</button></div></div></details>`;}
function update(el){const id=el.dataset.noteId,s=notes.get(id);if(!el.querySelector('textarea[data-note-text]'))el.innerHTML=body(id);const input=el.querySelector('[data-note-text]');if(document.activeElement!==input&&input.value!==s.text)input.value=s.text;const preview=el.querySelector('.note-preview');preview.textContent=s.text?`我的备注：${s.text.slice(0,240)}${s.text.length>240?'…':''}`:'';preview.hidden=!s.text;el.querySelector('summary').textContent='我的备注'+(s.text?' · 编辑':' · 添加');el.querySelector('.note-status').textContent=status(s);el.querySelector('[data-note-count]').textContent=s.text.length+'/10000';el.querySelector('[data-note-save]').disabled=s.saving;el.querySelector('.note-conflict').hidden=!s.conflict;el.querySelector('[data-note-remote]').value=s.cloudText;const setup=el.querySelector('.note-setup-link');if(setup)setup.hidden=s.availability!=='migration';}
export async function mountNotes(root=document){await notes.ready;root.querySelectorAll('.question-note').forEach(update);}
notes.addEventListener('change',e=>{document.querySelectorAll('.question-note').forEach(el=>{if(!e.detail.id||el.dataset.noteId===e.detail.id)update(el);});if(!e.detail.id&&['cloud','local'].includes(notes.availability))for(const [id,d] of notes.drafts)if(!d.conflict&&!notes.pending.has(id))schedule(id,100);});
function schedule(id,delay=1200){clearTimeout(timers.get(id));timers.set(id,setTimeout(()=>save(id),delay));}
async function save(id,keep=false){clearTimeout(timers.get(id));try{if(keep)await notes.keepDraft(id);else await notes.save(id);if(notes.get(id).dirty&&!notes.get(id).conflict)schedule(id);}catch{ /* NoteStore retains the draft and exposes the failure beside the editor. */ }}
document.addEventListener('input',e=>{if(!e.target.matches('[data-note-text]'))return;const id=e.target.closest('.question-note').dataset.noteId;notes.edit(id,e.target.value);if(!notes.get(id).conflict)schedule(id);});
document.addEventListener('click',e=>{const b=e.target.closest('button'),el=b?.closest('.question-note');if(!el)return;const id=el.dataset.noteId;if(b.hasAttribute('data-note-save'))save(id);if(b.hasAttribute('data-note-use-cloud')){clearTimeout(timers.get(id));notes.useCloud(id);update(el);}if(b.hasAttribute('data-note-keep'))save(id,true);});
window.addEventListener('focus',()=>{if(!notes.pending.size)notes.ready.then(()=>notes.reload());});
window.addEventListener('online',()=>notes.ready.then(async()=>{await notes.reload();for(const [id,d] of notes.drafts)if(!d.conflict)schedule(id);}));
